steps.script:
var main = tree.current_scene
for i in range(main.army_options.size()):
	if str(main.army_options[i].id) == "WPC46_E2E_Custodes":
		return i
return -1

for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) == 1 and str(u.meta.get("name", "")) == "Shield-Captain":
		var enh = u.meta.get("enhancements", [])
		var w := int(u.meta.stats.get("wounds", 0))
		var mw := int(u.models[0].get("wounds", 0))
		var done := bool(u.get("flags", {}).get("cus11e_listbuild_eagles_eye", false))
		GameState.state.meta["_c46_sc"] = uid
		print("[cus11e builder] ", uid, " enh=", enh, " W=", w, " model W=", mw, " listbuild=", done)
		return str(enh).contains("Eagle") and w == mw and done
return "no Shield-Captain"

var u = GameState.state.units[str(GameState.state.meta["_c46_sc"])]
var raw = ArmyListManager.cloud_army_cache.get("WPC46_E2E_Custodes", {})
var exported := -1
for k in raw.get("units", {}):
	var ru = raw.units[k]
	if str(ru.get("meta", {}).get("name", "")) == "Shield-Captain":
		exported = int(ru.meta.stats.wounds)
print("[cus11e builder] exported W=", exported, " game W=", u.meta.stats.wounds)
return exported > 0 and int(u.meta.stats.wounds) == exported + 1 and int(u.models[0].wounds) == exported + 1

var ds = tree.current_scene.get_node("DatasheetModal")
for l in ds.find_children("*", "Label", true, false):
	if str(l.text).begins_with("Enhancement:"):
		return l.text.contains("Eagle")
return false
